def calculate_scholarship(grades, leader, west, papers):
    """
    Calculate the total scholarship amount the student is eligible for based on their academic grades, class leadership, and research paper publications.

    Parameters:
        grades (list of int): A two-element list containing the student's academic grades [end of term average, class evaluation].
        leader (str): A string ('Y' or 'N') indicating if the student is a class leader.
        west (str): A string ('Y' or 'N') indicating if the student is from a western province.
        papers (int): An integer representing the number of research papers published by the student.

    Returns:
        int: The total scholarship amount the student is eligible for.
    """

    # Check for invalid inputs
    if len(grades) != 2:
        raise ValueError("'grades' must be a two-element list")
    if leader not in ['Y', 'N']:
        raise ValueError("'leader' must be a string ('Y' or 'N')")
    if west not in ['Y', 'N']:
        raise ValueError("'west' must be a string ('Y' or 'N')")
    if type(papers) is not int:
        raise ValueError("'papers' must be an integer")

    # Calculate the scholarship amount
    scholarship = 0
    if grades[0] > 80:
        scholarship += 8000
    if grades[0] > 85 and grades[1] > 80:
        scholarship += 4000
    if grades[0] > 90:
        scholarship += 2000
    if west == 'Y' and grades[0] > 85:
        scholarship += 1000
    if leader == 'Y' and grades[1] > 80:
        scholarship += 850
    if papers > 0:
        scholarship += 5000

    return scholarship

