def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D array to store the number of chatting pairs that can be separated by each aisle
    aisle_pairs = [[0 for _ in range(N)] for _ in range(M)]
    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        for i in range(Pi, Qi + 1):
            aisle_pairs[Xi][i] += 1
        for i in range(Xi + 1, M):
            aisle_pairs[i][Yi] += 1

    # Initialize a list to store the optimal aisle positions
    optimal_positions = []

    # Iterate over the rows and columns of the aisle_pairs array
    for i in range(M):
        for j in range(N):
            # If the current cell has a non-zero value, add the row and column indices to the list of optimal positions
            if aisle_pairs[i][j] > 0:
                optimal_positions.append((i, j))

    # Sort the list of optimal positions by the value of the first element (row index)
    optimal_positions.sort(key=lambda x: x[0])

    # Return the two space-separated strings representing the optimal row and column indices for the aisles
    return f"{optimal_positions[0][0]}", f"{optimal_positions[1][0]} {optimal_positions[1][1]}"
