def polynomial_to_string(n, coeffs):
    # Check if the input is valid
    if len(coeffs) != n+1:
        raise ValueError("Invalid input: length of coeffs must be n+1")

    # Build the string representation of the polynomial
    out = []
    for i in range(n+1):
        coeff = coeffs[i]
        if coeff != 0:
            term = ""
            if coeff < 0:
                term = "-"
            elif coeff > 0 and coeff != 1:
                term = "+"
            if coeff != 1:
                term += str(abs(coeff))
            if i != 0:
                term += "x^" + str(i)
            else:
                term += "x"
            out.append(term)

    # Return the string representation
    return "".join(out)
