def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last or n <= 0:
        return 0
    if n in memo:
        return memo[n]
    count = 1
    for i in range(1, n):
        if i <= last // 2 and n - i in memo:
            count += memo[n - i]
    memo[n] = count
    return count
