def calculate_arrangements(n, m, a):
    # Initialize the dp array with 0
    dp = [0] * (m + 1)
    dp[0] = 1

    # Calculate the number of arrangements for each pot
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[j - 1] >= i:
                dp[i] += dp[i - a[j - 1]]

    # modulo 10^6 + 7
    return dp[m] % (10**6 + 7)
